import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"Lab Word Documentation","description":"","frontmatter":{"docLocale":"en","counterpart":"/docs/","contentType":"overview","prev":false,"next":{"text":"Quick start","link":"/en/getting-started/quickstart"}},"headers":[],"relativePath":"en/docs/index.md","filePath":"en/docs/index.md"}'),i={name:"en/docs/index.md"};function o(d,e,s,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="lab-word-documentation" tabindex="-1">Lab Word Documentation <a class="header-anchor" href="#lab-word-documentation" aria-label="Permalink to &quot;Lab Word Documentation&quot;">​</a></h1><p>Lab Word is a laboratory digital twin. The application stores assets, Labs, objects and layouts. Backend programs provide device observations with sources and Tasks.</p><h2 id="choose-your-task" tabindex="-1">Choose Your Task <a class="header-anchor" href="#choose-your-task" aria-label="Permalink to &quot;Choose Your Task&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Starting point</th><th>Observable result</th></tr></thead><tbody><tr><td>Start the existing application</td><td><a href="./../getting-started/quickstart">Quick start</a></td><td>Ready API and accessible Web registration page</td></tr><tr><td>Inspect equipment models</td><td><a href="./../guides/lab-viewer">Lab and asset library</a></td><td>Render a model and publish a persistent GLB asset</td></tr><tr><td>Manage device lifecycle</td><td><a href="./../tutorials/entity-lifecycle">Entity lifecycle</a></td><td>Replace appearance and archive a stopped Entity</td></tr><tr><td>Complete the Foundation path</td><td><a href="./../tutorials/complete-foundation">Complete journey</a></td><td>Operate one shared Lab and reproduce its reference load</td></tr><tr><td>Change the project</td><td><a href="./../architecture/project-structure">Project structure</a></td><td>Locate application composition and business ownership</td></tr><tr><td>Look up interfaces</td><td><a href="./../reference/api">API</a> and <a href="./../reference/config">configuration</a></td><td>Find generated contracts and defaults</td></tr></tbody></table><h2 id="current-capabilities-and-plans" tabindex="-1">Current Capabilities And Plans <a class="header-anchor" href="#current-capabilities-and-plans" aria-label="Permalink to &quot;Current Capabilities And Plans&quot;">​</a></h2><p>The application provides identity, membership, knowledge, files and jobs through its <a href="./../guides/platform">platform capabilities</a>. Lab is the default entry after login. The accepted Viewer and Foundation previews provide the experience baseline.</p><p>Follow the paired tutorials from <a href="./../tutorials/persistent-assets">persistent assets</a> through identity, layouts, programs, synchronization, Tasks, history and lifecycle. The <a href="./../tutorials/complete-foundation">complete journey</a> uses one current checkout and one Lab throughout. It provides a separate, disposable 100 Entity, 20 device, two-browser reference load. Physical equipment integration remains future scope. <a href="./../architecture/lab-word">Product scope</a> defines these boundaries.</p><h2 id="reading-and-maintenance" tabindex="-1">Reading And Maintenance <a class="header-anchor" href="#reading-and-maintenance" aria-label="Permalink to &quot;Reading And Maintenance&quot;">​</a></h2><p>Tutorials grow the same Lab business code. Independent guides provide a task, prerequisites, source locations, commands, results and failure boundaries. Existing capabilities, previews and plans carry distinct status statements.</p><p>Chinese and English pages are paired by chapter. API and configuration facts are generated from implementation. Update relevant documentation and <a href="./../testing/feedback-loop">validation</a> with behavior changes; see <a href="./../guides/documentation">documentation maintenance</a>.</p><hr><p>Source version：<code>d3ff309e4aa6</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/d3ff309e4aa61231802ec2fb38cdbe7c44d8e7e1/docs/getting-started/documentation.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',12)])])}const b=t(i,[["render",o]]);export{h as __pageData,b as default};
